import hashlib
from compile_translation import ROOT,read,write,LEADING,TRAILING
from prepare_sklcard_428 import replace_slots
T={81:['…想要称手的东西，\n就带素材来。\n','先说好…老夫可\n不喜欢那些寻常货！\n','找些让人吃惊的稀奇货，\n拿过来吧。\n','…那样，老夫倒可以\n给你做点更气派的。\n','做的东西不同，\n素材的种类和数量也不同。\n','等这儿攒够一定的素材，\n老夫就凭灵感把它变成艺术品。\n','不过，做什么由老夫说了算。\n毕竟这是艺术嘛。\n','老夫可盼着呢！\n'],
82:['…欢迎光临！！\n今天想来点什么“艺术”？\n','…不要太重的？\n要藏在校服下面？\n','…你小子的爱好还真奇怪。\n','…算了，喜欢就没办法。\n多试试吧。\n'],83:['听说旅馆的独生女闷闷不乐，\n…整个商店街都在嚼舌根，真吵。\n','不过…那旅馆有一部分生意，\n确实靠着女儿的好名声。\n','听说可能是离家出走，\n希望别因不孝遭报应啊…\n','什么都不缺的大小姐想什么，\n老夫可不懂。\n'],84:['你…从城里来的？\n从那个满是恶意的荒凉地方啊…\n','老夫年轻时，\n对那边也挺熟悉…\n','这儿空气好，水好，米也香…\n…早把那边忘光了。\n'],
85:['…欢迎光临！！\n带来什么好货了吗？\n','嗯？…完二？\n那小毛孩又惹什么事了？\n','说起来，他是不是上过\n什么奇怪的搞笑电视节目？\n','难道…被星探看中去东京了！\n…准没错…是吧？\n'],86:['说起来，最近没见巽屋的完二。\n','那小子…装得一副坏样，\n可怎么看都只是胆大包天…\n','突然说要和暴走族干一架，\n抢了老夫得意的盾牌就走…\n','拿去打小孩子的架，\n简直是侮辱“艺术”…\n'],87:['完二那家伙，\n听说突然回来了啊。\n','问他原因也不肯说…\n真是个不孝的家伙…\n','不过…年轻时，\n谁没有不想说的事呢。\n'],88:['…欢迎光临！\n听说你和完二关系不错啊。\n','能把那匹野马收作小弟…\n你还真行啊。\n','嗯？不是小弟？\n…别害羞嘛。\n'],
89:['…怎么？你小子…\n看着挺兴奋啊。\n','林间学校？…不会吧！\n难道要带去当换洗衣服！\n','什么东西？当然是老夫的“艺术”！\n哇哈哈哈哈哈！\n','啊？…不是吗。\n'],90:['…你林间学校过得怎么样？\n…怎么一副泄气的样子？\n','吃饭差点吃死了？\n…那是什么情况？\n','趁现在才能享受的事，\n就应该多做做。\n'],91:['最近湿气太重，\n想集中精神都费劲…\n','湿气可是“艺术品”的天敌。\n','老夫有时真想…让它们\n全都尽情释放一下。\n','…当然，很危险就是了。\n'],92:['丸久家的理世，听说\n回这边来了啊…\n…老夫还没见到。\n','…为什么？老夫一直在这儿啊。\n其实老夫挺害羞的。\n','…问老夫是不是粉丝？\n…干吗非得回答你。\n','…随便啦！\n别打扰老夫专心搞“艺术”！\n'],
93:['丸久家的理世，听说回来了啊…\n','其实老夫和四六家、丸久家，\n关系都相当不错。\n','理世就像老夫的\n亲孙女一样啊…\n','也受了丸久老太太不少照顾…\n人情这东西真好啊。\n'],94:['你认识叫诸冈的老师吗？\n听说他被杀了…\n','以前他也来过这里，\n张口家长会，闭口心理健康…\n','像条小狗似的吵个没完…\n真是个麻烦家伙。\n','还说什么有害心理健康…\n他自己才不正常呢。\n'],95:['…嗯。最近总觉得…\n你小子身上有股霸气。\n','倒不是邪气…\n像战国武将那样的气势。\n','要是拿“艺术”去打无聊的架，\n老夫可饶不了你！\n'],96:['喜笑颜开…是吧？\n你小子真是神清气爽啊。\n','扫除了心中的污泥与恶意…\n这副表情不错…\n','能理解老夫“艺术”的是你，\n老夫很高兴…\n'],
97:['整天沉迷祭典之类的，\n暑假一眨眼就结束了。\n','不是说打铁要趁热吗！\n','你们也该趁满腔热情时，\n把想做的事做了。\n'],98:['你的霸气都开花了啊？\n碰上什么好事了吗？\n','嗯！！旅行…？\n','…给老夫带壬生仙贝就行。\n','…什么，不去京都？\n反正老夫也没期待…\n'],99:['…你是去修学旅行了吧？\n','难…难道带了伴手礼…\n不…不对，老夫才没期待！！\n','…总之，平平安安的，\n就是好事嘛。\n'],100:['嗯？…什么？\n“侦探王子”？\n','…真不顺耳…比起“王子”，\n老夫还是更喜欢“武将”…\n','…所以，这跟老夫的“艺术”\n有什么关系吗？\n','…没有？\n…白费老夫认真听了！\n'],
101:['秋意深…铁的气味亦染红叶色…\n怎么样？这句不错吧？\n','嗯…说没什么意义…\n唔…这可是老夫的日常啊…\n','算了…\n赶紧把素材拿出来吧…\n','…刚才那句可不是诗。\n'],102:['已经秋天了…和你认识\n都过了半年多了吧？\n','…嗯？\n问老夫脸上的刀疤？\n','男人之间，就别问那么细了…\n','…就当这也是\n老夫的“艺术”吧…\n'],103:['怎么…脸色都青了？\n…男人之间，老夫什么也不问。\n','守护想守护的东西…\n你这眼神，像条汉子。\n'],104:['…你的表情看着很难受啊。\n','男人有时候，\n确实得不动声色地忍耐…\n','…不过，也别把太多事憋心里。\n'],
105:['那怪雾想熄灭老夫工坊的炉火…\n唔…绝不饶它！\n','多亏这炉火，\n老夫手脚冰凉的毛病都好了…\n','这种严冬要是关门，\n老夫可怎么活啊…！\n'],106:['哪个时代，恶都不会绝迹…\n确实如此啊…\n','…记住了。\n邪恶必受惩罚，正义终将得胜。\n','这就是世间的道理。\n…虽然现在反过来了。\n','希望你用正直的眼光，\n看清究竟什么是恶…\n'],107:['打工？\n','不理解老夫的“艺术”，\n就别想在这儿打工。\n','这世上若真有谁\n能够理解老夫的“艺术”…\n','也就你了！\n哇哈哈哈哈哈！\n','不过，老夫压根儿\n没招过打工的就是了。\n'],
108:['那怪雾已经散得一干二净了啊。\n简直像从来没出现过。\n','干吗？一副得意洋洋的样子。\n难道这事跟你有关系？\n','哇哈哈哈哈哈！老夫喜欢！\n你这家伙活得很有艺术啊！\n'],109:['哟，来得好！\n新年快乐啊。\n','本想至少正月休息一下…\n看到你这张脸，创作欲又压不住了。\n','打起精神，\n开始新年的艺术创作吧！\n'],110:['哎呀，外头每天都冷得要命！\n但这里很热吧？\n','因为老夫燃烧的艺术之心，\n正打着刚强又可爱的节拍！\n','什么？说是炉火的缘故？你小子…\n嗯，确实快有１０００度了…\n'],111:['可能你们总是轻松进出，\n来参观的客人也比以前多了。\n','有人说想拜老夫为师，\n可艺术不是靠人教的。\n','倾听内心的声音，燃尽灵魂！\n这样才叫艺术！\n'],
112:['哟，怎么了。\n你不是要回城里去吗？\n','…嗯，看你这表情，\n像是还有什么事没做完啊。\n','算了，别说那些扫兴话。\n咱俩谁跟谁？尽管看吧！\n'],113:['唔…老夫收了一个家里的\n仓库藏品，那家的男主人去世了…\n','结果翻出了些意味深长的信…\n是情书啊…棘手吧？\n','扔了也太无情…\n可送回去又有点…\n','＞是久乃说过的那些信吗…\n','＞决定代为保管信件。\n'],114:['唔！你来得正好！\n','上次那些信啊…\n又翻出来一些。\n','方便的话，能再替老夫保管吗…\n','＞决定代为保管信件。\n']}
def main():
    T[90][0]='…你林间学校过得怎么样？\n…怎么垂头丧气的？\n'
    T[91][3]='…不过，很危险啊。\n'
    T[96][0]='喜笑颜开…啊？\n你小子真是神清气爽啊。\n'
    T[100][2]='…跟老夫的“艺术”\n有什么关系吗？\n'
    T[102][3]='…就说这也是老夫的“艺术”\n好了…\n'
    s='export_base/facility/msg_weapon.bmd.json';doc=read(ROOT/s)
    target=ROOT/'translation/batches/435_weapon_shop_legacy.generated.json';assert not target.exists()
    catalog={r['key']:r for r in read(ROOT/'translation/catalog.working.json')};rows=[]
    for i,ls in T.items():
        assert len(ls)==len(doc['texts'][i]['lines'])-(1 if i in (113,114) else 0)
        if i in (113,114):assert catalog[f'{s}:{i}:{len(ls)}'].get('translation')
        for j,plain in enumerate(ls):
            r=catalog[f'{s}:{i}:{j}'];assert not r.get('translation');old=r['original']
            full=replace_slots(old,plain);prefix=LEADING.match(old).group();suffix=TRAILING.search(old).group()
            body=full[len(prefix):len(full)-len(suffix)];assert prefix+body+suffix==full
            rows.append([i,j,doc['texts'][i]['id'],body])
    write(target,dict(status='draft',sources={s:rows},source_hashes={s:hashlib.sha256((ROOT/s).read_bytes()).hexdigest()},review_notes=['武器店81—114旧作日常对话完整补译，保留控制码、数字及分页；不宣称PQ运行时可达。']))
    print('Weapon shop pages:',len(rows))
if __name__=='__main__':main()
